foreach ($f in @('C:\Windows\System32\pwdrvio.sys', 'C:\Windows\System32\pwdspio.sys', 'C:\Windows\System32\drivers\pwdrvio.sys', 'C:\Windows\System32\drivers\pwdspio.sys')) {
