$ffUninst = 'C:\Program Files\Mozilla Firefox\uninstall\helper.exe'
if (Test-Path -LiteralPath $ffUninst) {
  $p = Start-Process -FilePath $ffUninst -ArgumentList '-ms' -Wait -PassThru
  Write-Output "Firefox helper.exe -ms exit=$($p.ExitCode)"
  Start-Sleep -Seconds 2
}
Get-Process | Where-Object { $_.Name -match 'firefox|mozilla|helper|updater' } | Stop-Process -Force -ErrorAction SilentlyContinue

$ffPaths = @(
  'C:\Program Files\Mozilla Firefox',
  'C:\Program Files (x86)\Mozilla Firefox',
  'C:\ProgramData\Mozilla*',
  'C:\ProgramData\Microsoft\Windows\Start Menu\Programs\Firefox.lnk',
