  'HKLM:\SOFTWARE\Mozilla',
  'HKLM:\SOFTWARE\WOW6432Node\Mozilla',
  'HKLM:\SOFTWARE\Policies\Mozilla',
  'HKCU:\SOFTWARE\Mozilla',
  'HKCU:\SOFTWARE\Policies\Mozilla',
