    Remove-Item -LiteralPath $rk -Recurse -Force -ErrorAction SilentlyContinue
    Write-Output "Removed reg: $rk"
  }
}
if (Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\RegisteredApplications' -Name 'Firefox-308046B0AF4A39CB' -ErrorAction SilentlyContinue) {
  Remove-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\RegisteredApplications' -Name 'Firefox-308046B0AF4A39CB' -Force
  Write-Output 'Removed RegisteredApplications Firefox-308046B0AF4A39CB'
}

Write-Output '=== STEP 3: MINITOOL PURGE & DRIVERS ==='
foreach ($svc in @('pwdrvio', 'pwdspio')) {
  & sc.exe stop $svc | Out-Null
  & sc.exe delete $svc | Write-Output
