foreach ($drv in @('C:\Windows\System32\pwdspio.sys', 'C:\Windows\System32\pwdrvio.sys')) {
  if (Test-Path -LiteralPath $drv) {
    Remove-Item -LiteralPath $drv -Force -ErrorAction SilentlyContinue
