      $ok = $k32::MoveFileEx($drv, $null, 4)
      Write-Output "Locked kernel driver queued for reboot deletion ($ok): $drv"
    } else {
      Write-Output "Deleted driver immediately: $drv"
    }
  }
}

foreach ($mp in @(
  'C:\ProgramData\Microsoft\Windows\Start Menu\Programs\MiniTool Partition Wizard 12',
  'C:\Users\Admin\AppData\Roaming\Microsoft\Windows\Recent\_Getintopc.com_MiniTool_Partition_Wizard_Technician_12.9 (2).rar.lnk'
